    idPastilha,
    quantidade
];

return [msg, null];

const resultado = msg.payload;

// Verifica se o estoque foi atualizado
if (!resultado || resultado.affectedRows === 0) {

    msg.statusCode = 400;

    msg.payload = {
        sucesso: false,
        mensagem: "Estoque insuficiente! Não foi possível realizar a saída."
    };

    msg.headers = {
        "Access-Control-Allow-Origin": "*",
        "Content-Type": "application/json"
    };

    return [null, msg];
}

// Registrar a movimentação com o usuário correto
