    "Access-Control-Allow-Origin": "*"
};

return msg;

let dados = msg.payload;

try {
    if (typeof dados === "string") {
        dados = JSON.parse(dados);
    }

    const codigo = String(dados.codigo || "").trim();
    const modelo = String(dados.modelo || "").trim();
    const codigoBarras = String(dados.codigo_barras || "").trim();
    const idFabricante = Number(dados.id_fabricante);
    const idFornecedor = Number(dados.id_fornecedor);
    const estoqueMinimo = Number(dados.estoque_minimo);
    const quantidadeInicial = Number(dados.quantidade_inicial);
    const localizacao = String(dados.localizacao || "Almoxarifado").trim();
    const descricao = String(dados.descricao || "");

    if (!codigo || !modelo || !codigoBarras ||
        !Number.isInteger(idFabricante) || idFabricante <= 0 ||
        !Number.isInteger(idFornecedor) || idFornecedor <= 0 ||
        !Number.isInteger(estoqueMinimo) || estoqueMinimo < 0 ||
        !Number.isInteger(quantidadeInicial) || quantidadeInicial < 0) {
        throw new Error("Preencha os campos obrigatórios corretamente.");
    }

    msg.quantidadeInicial = quantidadeInicial;
    msg.localizacao = localizacao;

    msg.topic = "INSERT INTO pastilhas (codigo, codigo_barras, modelo, descricao, id_fabricante, id_fornecedor, estoque_minimo) VALUES (?, ?, ?, ?, ?, ?, ?)";
    msg.payload = [codigo, codigoBarras, modelo, descricao, idFabricante, idFornecedor, estoqueMinimo];

    return [msg, null];

} catch (erro) {
    msg.statusCode = 400;
    msg.payload = { sucesso: false, mensagem: erro.message };
    return [null, msg];
}

const resultado = msg.payload;
const idPastilha = resultado && resultado.insertId;

if (!idPastilha) {
    throw new Error("Não foi possível obter o ID da pastilha.");
}

msg.topic = "INSERT INTO estoque (id_pastilha, quantidade_atual, localizacao) VALUES (?, ?, ?)";
msg.payload = [idPastilha, msg.quantidadeInicial, msg.localizacao];

return msg;

msg.statusCode = 201;
msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Content-Type": "application/json"
};
msg.payload = {
    sucesso: true,
    mensagem: "Pastilha cadastrada com sucesso!"
};
return msg;

msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Content-Type": "application/json"
};
return msg;

msg.statusCode = 400;

let mensagem = "Não foi possível cadastrar a pastilha.";

if (msg.error && msg.error.code === "ER_DUP_ENTRY") {
    mensagem = "Este código ou código de barras já está cadastrado.";
}

msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Content-Type": "application/json"
};

msg.payload = {
    sucesso: false,
    mensagem: mensagem
};

return msg;

const idPastilha = Number(msg.req && msg.req.params && msg.req.params.id);

msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Content-Type": "application/json"
};

if (!Number.isInteger(idPastilha) || idPastilha <= 0) {
    msg.statusCode = 400;
    msg.payload = {
        sucesso: false,
        mensagem: "ID da pastilha inválido."
    };
    return [null, msg];
}

msg.topic = `
    DELETE p, e
    FROM pastilhas p
    INNER JOIN estoque e ON e.id_pastilha = p.id_pastilha
    WHERE p.id_pastilha = ?
      AND NOT EXISTS (
          SELECT 1
          FROM movimentacoes m
          WHERE m.id_pastilha = p.id_pastilha
      )
`;

msg.payload = [idPastilha];
return [msg, null];

const resultado = msg.payload;
const removidos = resultado && Number(resultado.affectedRows || 0);

msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Content-Type": "application/json"
};

if (removidos > 0) {
    msg.statusCode = 200;
    msg.payload = {
        sucesso: true,
        mensagem: "Pastilha excluída com sucesso."
    };
} else {
    msg.statusCode = 409;
    msg.payload = {
        sucesso: false,
        mensagem: "A pastilha não foi encontrada ou possui movimentações registradas. O histórico foi preservado."
    };
}

return msg;

msg.statusCode = 204;
msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, DELETE, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type"
};
msg.payload = "";
return msg;

try {
    let dados = msg.payload;
    if (typeof dados === "string") dados = JSON.parse(dados);

    const nome = String(dados.nome || "").trim();
    const email = String(dados.email || "").trim().toLowerCase();
    const senha = String(dados.senha || "");

    if (!nome || nome.length > 100) {
        throw new Error("Informe um nome válido.");
    }
    if (!email || email.length > 100 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        throw new Error("Informe um e-mail válido.");
    }
    if (senha.length < 8) {
        throw new Error("A senha deve possuir pelo menos 8 caracteres.");
    }
    if (senha.length > 72) {
        throw new Error("A senha deve possuir no máximo 72 caracteres.");
    }

    const hash = bcrypt.hashSync(senha, 12);

    msg.topic = "INSERT INTO usuarios (nome, email, senha) VALUES (?, ?, ?)";
    msg.payload = [nome, email, hash];
    return [msg, null];

} catch (erro) {
    msg.statusCode = 400;
    msg.payload = { sucesso: false, mensagem: erro.message };
    return [null, msg];
}

msg.statusCode = 201;
msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Content-Type": "application/json"
};
msg.payload = {
    sucesso: true,
    mensagem: "Usuário cadastrado com sucesso!"
};
return msg;

const duplicado = msg.error && msg.error.code === "ER_DUP_ENTRY";
msg.statusCode = duplicado ? 409 : 500;
msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Content-Type": "application/json"
};
msg.payload = {
    sucesso: false,
    mensagem: duplicado ? "Este e-mail já está cadastrado." : "Não foi possível cadastrar o usuário."
};
return msg;

try {
    let dados = msg.payload;
    if (typeof dados === "string") dados = JSON.parse(dados);

    const email = String(dados.email || "").trim().toLowerCase();
    const senha = String(dados.senha || "");

    if (!email || !senha) {
        throw new Error("Informe o e-mail e a senha.");
    }

    msg.senhaLogin = senha;
    msg.topic = "SELECT id_usuario, nome, email, senha FROM usuarios WHERE email = ? LIMIT 1";
    msg.payload = [email];
    return [msg, null];

} catch (erro) {
    msg.statusCode = 400;
    msg.payload = { sucesso: false, mensagem: erro.message };
    return [null, msg];
}

const usuarios = msg.payload;
const usuario = Array.isArray(usuarios) ? usuarios[0] : null;

msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Content-Type": "application/json"
};

if (!usuario || !bcrypt.compareSync(msg.senhaLogin, usuario.senha)) {
    msg.statusCode = 401;
    msg.payload = {
        sucesso: false,
        mensagem: "E-mail ou senha incorretos."
    };
    return msg;
}

msg.statusCode = 200;
msg.payload = {
    sucesso: true,
    mensagem: "Login realizado com sucesso!",
    usuario: {
        id_usuario: usuario.id_usuario,
        nome: usuario.nome,
        email: usuario.email
    }
};
return msg;

msg.statusCode = 500;
msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Content-Type": "application/json"
};
msg.payload = {
    sucesso: false,
    mensagem: "Não foi possível realizar o login. Tente novamente."
};
return msg;

msg.statusCode = 204;
msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type"
};
msg.payload = "";
return msg;
